static gboolean delete_window(GtkWidget*,GdkEvent*,gpointer);static void load_user_patterns(void);static void theme_changed(GtkComboBox*,gpointer);static gboolean first_tour(gpointer);static void update(void);static void action(GtkWidget*,gpointer);static void tour_show(void);static void save_canvas(void);static void load_canvas(void);static void edit_rules(void);static void edit_borders(void);static void save_pattern(void);static void copy_selection(void);static void paste_selection(void);static void apply_theme(void);static void save_preferences(void);
